-- Additive business schema. Monetary amounts are integer cents; platform points use shop_id=0.
CREATE TABLE IF NOT EXISTS hx_shop (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, county VARCHAR(100) NOT NULL, kind VARCHAR(20) NOT NULL, owner_id BIGINT NOT NULL, merchant_no VARCHAR(80), payment_ready BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE', settings TEXT);
CREATE TABLE IF NOT EXISTS hx_merchant_onboarding (shop_id BIGINT PRIMARY KEY, subject_type VARCHAR(24), subject_name VARCHAR(160), legal_representative VARCHAR(80), license_no VARCHAR(32), contact_phone VARCHAR(32), settlement_bank VARCHAR(120), settlement_account_ref VARCHAR(128), attachment_ids TEXT, application_ref VARCHAR(100), application_status VARCHAR(24) NOT NULL DEFAULT 'NOT_SUBMITTED', authorization_ref VARCHAR(100), authorization_status VARCHAR(24) NOT NULL DEFAULT 'NOT_SUBMITTED', transfer_auth_ref VARCHAR(100), transfer_auth_status VARCHAR(24) NOT NULL DEFAULT 'NOT_SUBMITTED', transfer_auth_at TIMESTAMP NULL, app_id VARCHAR(80), merchant_no VARCHAR(80), certificate_ref VARCHAR(100), certificate_status VARCHAR(24) NOT NULL DEFAULT 'NOT_SUBMITTED', certificate_serial VARCHAR(100), expires_at DATE, contracted_fee_bps INT, settlement_days INT, abnormal_reason VARCHAR(500), rejection_reason VARCHAR(500), updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_policy (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, policy_type VARCHAR(40) NOT NULL, version VARCHAR(40) NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, status VARCHAR(20) NOT NULL, published_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(shop_id,policy_type,version));
CREATE TABLE IF NOT EXISTS hx_policy_consent (member_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, policy_type VARCHAR(40) NOT NULL, version VARCHAR(40) NOT NULL, source VARCHAR(32) NOT NULL, consented_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(member_id,shop_id,policy_type,version));
CREATE TABLE IF NOT EXISTS hx_pick_task (order_id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, status VARCHAR(24) NOT NULL, started_by BIGINT, started_at TIMESTAMP NULL, completed_by BIGINT, completed_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS hx_direct_sale_aftersale (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, customer_refund_id VARCHAR(64) NOT NULL UNIQUE, wholesale_order_id VARCHAR(64) NOT NULL, wholesale_refund_id VARCHAR(64), sku_id VARCHAR(64) NOT NULL, qty INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_member (id BIGINT PRIMARY KEY, name VARCHAR(80) NOT NULL, phone VARCHAR(32), authorized BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS hx_staff (user_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, role_code VARCHAR(24) NOT NULL, PRIMARY KEY(user_id,shop_id));
CREATE TABLE IF NOT EXISTS hx_agent (id BIGINT PRIMARY KEY AUTO_INCREMENT, member_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, parent_id BIGINT, rank_no INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', approved_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(member_id,shop_id));
CREATE TABLE IF NOT EXISTS hx_agent_region (agent_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, region_path VARCHAR(100) NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(agent_id,region_path));
CREATE INDEX idx_hx_agent_region_shop_path ON hx_agent_region(shop_id,region_path,agent_id);
CREATE INDEX idx_hx_agent_shop_parent ON hx_agent(shop_id,parent_id,id);
CREATE TABLE IF NOT EXISTS hx_binding (member_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, bound_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(member_id,shop_id));
CREATE TABLE IF NOT EXISTS hx_invite (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, channel VARCHAR(40) NOT NULL, expires_at TIMESTAMP NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS hx_sku (id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, name VARCHAR(160) NOT NULL, spec VARCHAR(160), asset VARCHAR(100), retail BIGINT NOT NULL, cloud_price BIGINT NOT NULL, center_price BIGINT NOT NULL, owner_price BIGINT NOT NULL, point_price BIGINT NOT NULL DEFAULT 0, available INT NOT NULL DEFAULT 0, locked INT NOT NULL DEFAULT 0, defective INT NOT NULL DEFAULT 0, warning_qty INT NOT NULL DEFAULT 10, box_size INT NOT NULL DEFAULT 24, min_boxes INT NOT NULL DEFAULT 2, min_qty INT NOT NULL DEFAULT 1, mix_group VARCHAR(64), mix_units INT NOT NULL DEFAULT 1, status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE', PRIMARY KEY(shop_id,id));
CREATE TABLE IF NOT EXISTS hx_rule (id BIGINT PRIMARY KEY AUTO_INCREMENT, cloud_bps INT NOT NULL, center_bps INT NOT NULL, owner_bps INT NOT NULL, effective_at TIMESTAMP NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_order (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, buyer_id BIGINT NOT NULL, destination_shop_id BIGINT, cross_authorization_id VARCHAR(64), order_type VARCHAR(24) NOT NULL, status VARCHAR(24) NOT NULL, subtotal BIGINT NOT NULL, discount BIGINT NOT NULL DEFAULT 0, freight BIGINT NOT NULL DEFAULT 0, total BIGINT NOT NULL, refunded BIGINT NOT NULL DEFAULT 0, points_used BIGINT NOT NULL DEFAULT 0, points_scope BIGINT NOT NULL DEFAULT 0, points_earned BIGINT NOT NULL DEFAULT 0, shop_points_earned BIGINT NOT NULL DEFAULT 0, merchant_no VARCHAR(80) NOT NULL, rule_id BIGINT NOT NULL, address_json TEXT NOT NULL, remark VARCHAR(800) NOT NULL DEFAULT '', shipping_json TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMP NOT NULL, completed_at TIMESTAMP NULL);
CREATE INDEX hx_order_shop ON hx_order(shop_id,created_at);
CREATE TABLE IF NOT EXISTS hx_order_line (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id VARCHAR(64) NOT NULL, sku_id VARCHAR(64) NOT NULL, name VARCHAR(160) NOT NULL, qty INT NOT NULL, refunded_qty INT NOT NULL DEFAULT 0, unit_price BIGINT NOT NULL, paid BIGINT NOT NULL, refunded_paid BIGINT NOT NULL DEFAULT 0, snapshot_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hx_earning (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id VARCHAR(64) NOT NULL, line_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, earning_type VARCHAR(24) NOT NULL, amount BIGINT NOT NULL, reversed BIGINT NOT NULL DEFAULT 0, frozen_amount BIGINT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'PENDING');
CREATE TABLE IF NOT EXISTS hx_wallet (shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, available BIGINT NOT NULL DEFAULT 0, frozen BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(shop_id,member_id));
CREATE TABLE IF NOT EXISTS hx_ledger (id BIGINT PRIMARY KEY AUTO_INCREMENT, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, category VARCHAR(32) NOT NULL, amount BIGINT NOT NULL, reference_id VARCHAR(64) NOT NULL, detail TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX hx_ledger_receipt_lookup ON hx_ledger(reference_id, shop_id, category, id);
CREATE INDEX hx_ledger_scope ON hx_ledger(shop_id,member_id);
CREATE TABLE IF NOT EXISTS hx_inventory_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, shop_id BIGINT NOT NULL, sku_id VARCHAR(64) NOT NULL, available_delta INT NOT NULL, locked_delta INT NOT NULL, defective_delta INT NOT NULL DEFAULT 0, reason VARCHAR(32) NOT NULL, reference_id VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_payment (id VARCHAR(64) PRIMARY KEY, order_id VARCHAR(64) NOT NULL UNIQUE, merchant_no VARCHAR(80) NOT NULL, amount BIGINT NOT NULL, status VARCHAR(24) NOT NULL, channel_ref VARCHAR(100) UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_refund (id VARCHAR(64) PRIMARY KEY, order_id VARCHAR(64) NOT NULL, line_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, qty INT NOT NULL, amount BIGINT NOT NULL, refund_type VARCHAR(24) NOT NULL, status VARCHAR(24) NOT NULL, reason VARCHAR(500) NOT NULL, restock_qty INT NOT NULL DEFAULT 0, review_by BIGINT, review_note VARCHAR(500), evidence_json TEXT, return_json TEXT, exchange_json TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_withdrawal (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, amount BIGINT NOT NULL, fee BIGINT NOT NULL, net BIGINT NOT NULL, channel VARCHAR(32) NOT NULL, account_ref VARCHAR(128) NOT NULL, merchant_no VARCHAR(80), status VARCHAR(24) NOT NULL, reviewer BIGINT, reviewed_at TIMESTAMP NULL, reason VARCHAR(500), channel_ref VARCHAR(100), provider_out_bill_no VARCHAR(32), provider_bill_no VARCHAR(64), provider_state VARCHAR(32), provider_package TEXT, provider_updated_at TIMESTAMP NULL, payout_operator BIGINT, payout_evidence_json TEXT, payout_reason VARCHAR(500), payout_recorded_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_points (shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, available BIGINT NOT NULL DEFAULT 0, pending_reclaim BIGINT NOT NULL DEFAULT 0, frozen BOOLEAN NOT NULL DEFAULT FALSE, batches_initialized BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(shop_id,member_id));
CREATE TABLE IF NOT EXISTS hx_point_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, amount BIGINT NOT NULL, kind VARCHAR(32) NOT NULL, reference_id VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX hx_points_scope ON hx_point_log(shop_id,member_id,created_at);
CREATE TABLE IF NOT EXISTS hx_document (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, kind VARCHAR(40) NOT NULL, status VARCHAR(24) NOT NULL, body_json TEXT NOT NULL, reviewer BIGINT, review_note VARCHAR(500), campaign_ref VARCHAR(64), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE hx_document MODIFY body_json MEDIUMTEXT NOT NULL;
CREATE INDEX hx_document_scope ON hx_document(shop_id,kind);
CREATE TABLE IF NOT EXISTS hx_audit (ip_masked VARCHAR(80) NOT NULL DEFAULT '', request_id VARCHAR(100) NOT NULL DEFAULT '', source VARCHAR(16) NOT NULL DEFAULT 'UNKNOWN', actor_kind VARCHAR(16) NOT NULL DEFAULT 'UNKNOWN', id BIGINT PRIMARY KEY AUTO_INCREMENT, shop_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, action VARCHAR(64) NOT NULL, reference_id VARCHAR(64) NOT NULL, before_json TEXT, after_json TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_idempotency (actor_key VARCHAR(80) NOT NULL, request_key VARCHAR(100) NOT NULL, operation VARCHAR(100) NOT NULL, request_hash VARCHAR(64) NOT NULL, response_json TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(actor_key,request_key));
CREATE TABLE IF NOT EXISTS hx_message (body_text TEXT, event_type VARCHAR(32) NOT NULL DEFAULT 'SYSTEM', id BIGINT PRIMARY KEY AUTO_INCREMENT, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, reference_id VARCHAR(64), is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_session (token_hash VARCHAR(64) PRIMARY KEY, member_id BIGINT NOT NULL, expires_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS hx_wechat_account (app_id VARCHAR(80) NOT NULL, open_id VARCHAR(100) NOT NULL, member_id BIGINT NOT NULL, PRIMARY KEY(app_id,open_id), UNIQUE(member_id));
CREATE TABLE IF NOT EXISTS hx_attachment (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, purpose VARCHAR(24) NOT NULL, mime VARCHAR(40) NOT NULL, iv VARBINARY(12) NOT NULL, cipher_bytes LONGBLOB NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS hx_marketing_usage (order_id VARCHAR(64) NOT NULL, campaign_id VARCHAR(64) NOT NULL, qty BIGINT NOT NULL, PRIMARY KEY(order_id,campaign_id));

CREATE TABLE IF NOT EXISTS hx_channel_event (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, event_type VARCHAR(32) NOT NULL, business_id VARCHAR(64) NOT NULL, channel_ref VARCHAR(100) NOT NULL, payload_json TEXT NOT NULL, status VARCHAR(24) NOT NULL, error_message VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, processed_at TIMESTAMP NULL);

CREATE TABLE IF NOT EXISTS hx_point_batch (id BIGINT PRIMARY KEY AUTO_INCREMENT, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, remaining BIGINT NOT NULL, expired BIGINT NOT NULL DEFAULT 0, reclaimed_expired BIGINT NOT NULL DEFAULT 0, expires_at TIMESTAMP NULL, origin_kind VARCHAR(32) NOT NULL, origin_ref VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX hx_batch_account(shop_id,member_id,expires_at));
CREATE TABLE IF NOT EXISTS hx_point_use (id BIGINT PRIMARY KEY AUTO_INCREMENT, batch_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, amount BIGINT NOT NULL, restored BIGINT NOT NULL DEFAULT 0, kind VARCHAR(32) NOT NULL, reference_id VARCHAR(64) NOT NULL, INDEX hx_use_reference(shop_id,member_id,reference_id));

CREATE TABLE IF NOT EXISTS hx_referral (shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, inviter_agent_id BIGINT NOT NULL, inviter_member_id BIGINT NOT NULL, invite_id VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(shop_id,member_id));
CREATE TABLE IF NOT EXISTS hx_invitation_order (order_id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, campaign_id VARCHAR(64) NOT NULL, buyer_id BIGINT NOT NULL, inviter_agent_id BIGINT NOT NULL, qualifying_amount BIGINT NOT NULL, threshold_amount BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS hx_invitation_reward (campaign_id VARCHAR(64) NOT NULL, buyer_id BIGINT NOT NULL, milestone INT NOT NULL, order_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, inviter_agent_id BIGINT NOT NULL, amount BIGINT NOT NULL, snapshot_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(campaign_id,buyer_id,milestone));

CREATE TABLE IF NOT EXISTS hx_group_buy (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, campaign_id VARCHAR(64) NOT NULL, leader_id BIGINT NOT NULL, sku_id VARCHAR(64) NOT NULL, target_size INT NOT NULL, price BIGINT NOT NULL, status VARCHAR(24) NOT NULL, expires_at TIMESTAMP NOT NULL, formed_at TIMESTAMP NULL, snapshot_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_group_member (group_id VARCHAR(64) NOT NULL, member_id BIGINT NOT NULL, order_id VARCHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(group_id,member_id));
CREATE TABLE IF NOT EXISTS hx_group_refund (refund_id VARCHAR(64) PRIMARY KEY, status VARCHAR(24) NOT NULL, attempts INT NOT NULL DEFAULT 0, next_attempt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_error VARCHAR(1000), updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS hx_assessment_period (id VARCHAR(64) PRIMARY KEY, rule_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, member_id BIGINT NOT NULL, rank_no INT NOT NULL, period_start VARCHAR(10) NOT NULL, period_end VARCHAR(10) NOT NULL, passed BOOLEAN NOT NULL, failures INT NOT NULL, evaluation_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(rule_id,agent_id,period_start));

CREATE TABLE IF NOT EXISTS hx_reconciliation_batch (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, statement_date VARCHAR(10) NOT NULL, source VARCHAR(24) NOT NULL, content_hash VARCHAR(64) NOT NULL, total_rows INT NOT NULL, processed_rows INT NOT NULL DEFAULT 0, status VARCHAR(24) NOT NULL, created_by VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(shop_id,statement_date,content_hash));
CREATE TABLE IF NOT EXISTS hx_reconciliation_line (id VARCHAR(64) PRIMARY KEY, batch_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, row_no INT NOT NULL, operation VARCHAR(24) NOT NULL, business_id VARCHAR(64) NOT NULL, channel_ref VARCHAR(100) NOT NULL, merchant_no VARCHAR(80) NOT NULL, channel_amount BIGINT NOT NULL, expected_amount BIGINT, difference BIGINT, status VARCHAR(32) NOT NULL, note VARCHAR(500), INDEX hx_reconcile_batch(batch_id,row_no));
CREATE TABLE IF NOT EXISTS hx_reconciliation_adjustment (id VARCHAR(64) PRIMARY KEY, line_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, operation VARCHAR(24) NOT NULL, business_id VARCHAR(64) NOT NULL, channel_ref VARCHAR(100) NOT NULL, amount BIGINT NOT NULL, status VARCHAR(24) NOT NULL, requested_by VARCHAR(80) NOT NULL, reason VARCHAR(500) NOT NULL, evidence_json TEXT NOT NULL, reviewed_by VARCHAR(80), review_reason VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TIMESTAMP NULL, INDEX hx_adjust_business(shop_id,operation,business_id,channel_ref));

CREATE TABLE IF NOT EXISTS hx_link_participant (campaign_id VARCHAR(64) NOT NULL, agent_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, origin_parent_id BIGINT, marketing_parent_id BIGINT, role VARCHAR(16) NOT NULL, status VARCHAR(24) NOT NULL, promoted_once BOOLEAN NOT NULL DEFAULT FALSE, joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(campaign_id,agent_id));
CREATE TABLE IF NOT EXISTS hx_link_order (order_id VARCHAR(64) PRIMARY KEY, campaign_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, qualifying_amount BIGINT NOT NULL, threshold_amount BIGINT NOT NULL, is_new_agent BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX hx_link_qualify(campaign_id,agent_id));
CREATE TABLE IF NOT EXISTS hx_link_reward (order_id VARCHAR(64) NOT NULL, campaign_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, subject_agent_id BIGINT NOT NULL, recipient_agent_id BIGINT NOT NULL, reward_type VARCHAR(24) NOT NULL, amount BIGINT NOT NULL, snapshot_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(order_id,recipient_agent_id,reward_type), INDEX hx_link_cap(campaign_id,recipient_agent_id));

CREATE TABLE IF NOT EXISTS hx_sku_detail (shop_id BIGINT NOT NULL, sku_id VARCHAR(64) NOT NULL, category VARCHAR(80) NOT NULL DEFAULT '', brand VARCHAR(80) NOT NULL DEFAULT '', product_group VARCHAR(64) NOT NULL DEFAULT '', description TEXT, freight_id VARCHAR(64) NOT NULL DEFAULT '', weight_grams INT NOT NULL DEFAULT 1000, allow_loose BOOLEAN NOT NULL DEFAULT TRUE, gallery_json TEXT, retail_min BIGINT NOT NULL DEFAULT 0, retail_max BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(shop_id,sku_id));

CREATE TABLE IF NOT EXISTS hx_point_risk_case (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, status VARCHAR(24) NOT NULL, rule_json TEXT NOT NULL, reviewer VARCHAR(80), review_note VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TIMESTAMP NULL, INDEX hx_point_risk_account(shop_id,member_id,status));

CREATE TABLE IF NOT EXISTS hx_report_job (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, created_by BIGINT NOT NULL, staff_actor BOOLEAN NOT NULL, platform_actor BOOLEAN NOT NULL, filters_json TEXT NOT NULL, status VARCHAR(24) NOT NULL, total_rows BIGINT NOT NULL DEFAULT 0, processed_rows BIGINT NOT NULL DEFAULT 0, cursor_id BIGINT NOT NULL DEFAULT 0, error_message VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, snapshot_at TIMESTAMP NULL, completed_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS hx_report_line (job_id VARCHAR(64) NOT NULL, line_id BIGINT NOT NULL, order_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, shop_name VARCHAR(160), county VARCHAR(100), buyer_id BIGINT NOT NULL, buyer_name VARCHAR(160), sku_id VARCHAR(64) NOT NULL, sku_name VARCHAR(160), category VARCHAR(80), qty BIGINT NOT NULL, refunded_qty BIGINT NOT NULL, paid BIGINT NOT NULL, refunded_paid BIGINT NOT NULL, snapshot_json TEXT NOT NULL, order_status VARCHAR(24), order_type VARCHAR(24), created_at TIMESTAMP NOT NULL, business_day VARCHAR(10), cost_known BOOLEAN NOT NULL DEFAULT FALSE, agent_id BIGINT NOT NULL DEFAULT 0, agent_name VARCHAR(160), rank_no INT NOT NULL DEFAULT 0, net_cost BIGINT NOT NULL DEFAULT 0, earnings BIGINT NOT NULL DEFAULT 0, matched BOOLEAN NOT NULL DEFAULT FALSE, processed BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(job_id,line_id), INDEX hx_report_group(job_id,matched,shop_id,sku_id));
CREATE TABLE IF NOT EXISTS hx_report_stock (job_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, sku_id VARCHAR(64) NOT NULL, sku_name VARCHAR(160), available INT NOT NULL, locked INT NOT NULL, defective INT NOT NULL, warning_qty INT NOT NULL, in_transit BIGINT NOT NULL DEFAULT 0, average_stock DECIMAL(20,4) NOT NULL DEFAULT 0, PRIMARY KEY(job_id,shop_id,sku_id));
